import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import {
  Menu as MenuPrimitive,
  useMenu,
  useMenuContext,
  useMenuItemContext,
} from '@ark-ui/solid/menu';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { CheckIcon, ChevronDownIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui/Icons';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import styles from './Menu.module.css';

type MenuIndicatorPosition = 'start' | 'end' | 'none';
type MenuItemTone = 'default' | 'destructive';
type MenuItemProps = ComponentProps<typeof MenuPrimitive.Item> & {
  tone?: MenuItemTone;
};
type MenuCheckboxItemProps = ComponentProps<typeof MenuPrimitive.CheckboxItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRadioItemProps = ComponentProps<typeof MenuPrimitive.RadioItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRootProps = ComponentProps<typeof MenuPrimitive.Root> & OverlayPortalProps;
type MenuRootProviderProps = ComponentProps<typeof MenuPrimitive.RootProvider> & OverlayPortalProps;

function Menu(props: MenuRootProps) {
  const [local, others] = splitProps(props, [
    'children',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <MenuPrimitive.Root
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </MenuPrimitive.Root>
    </OverlayPortalProvider>
  );
}

function MenuRootProvider(props: MenuRootProviderProps) {
  const [local, others] = splitProps(props, [
    'children',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <MenuPrimitive.RootProvider
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
      >
        {local.children}
      </MenuPrimitive.RootProvider>
    </OverlayPortalProvider>
  );
}

function MenuTrigger(props: ComponentProps<typeof MenuPrimitive.Trigger>) {
  return <MenuPrimitive.Trigger {...props} data-slot="menu-trigger" />;
}

function MenuIndicator(props: ComponentProps<typeof MenuPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="menu-indicator"
    >
      {resolvedChildren() ?? <ChevronDownIcon />}
    </MenuPrimitive.Indicator>
  );
}

function MenuContextTrigger(props: ComponentProps<typeof MenuPrimitive.ContextTrigger>) {
  return <MenuPrimitive.ContextTrigger {...props} data-slot="menu-context-trigger" />;
}

function MenuPositioner(props: ComponentProps<typeof MenuPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <MenuPrimitive.Positioner
        class={clsx(styles.positioner, local.class)}
        {...others}
        data-slot="menu-positioner"
      />
    </OverlayPortal>
  );
}

function MenuContent(props: ComponentProps<typeof MenuPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="menu-content"
    />
  );
}

function MenuViewport(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.viewport, local.class)}
      {...others}
      data-scope="menu"
      data-part="viewport"
      data-slot="menu-viewport"
    />
  );
}

function MenuArrow(props: ComponentProps<typeof MenuPrimitive.Arrow>) {
  const [local, others] = splitProps(props, ['children']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.Arrow {...others} data-slot="menu-arrow">
      {resolvedChildren() ?? <MenuArrowTip />}
    </MenuPrimitive.Arrow>
  );
}

function MenuArrowTip(props: ComponentProps<typeof MenuPrimitive.ArrowTip>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ArrowTip
      class={clsx(styles.arrowTip, local.class)}
      {...others}
      data-slot="menu-arrow-tip"
    />
  );
}

function MenuItem(props: MenuItemProps) {
  const [local, others] = splitProps(props, ['class', 'tone']);

  return (
    <MenuPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-tone={local.tone ?? 'default'}
      data-slot="menu-item"
    />
  );
}

function MenuTriggerItem(props: ComponentProps<typeof MenuPrimitive.TriggerItem>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.TriggerItem
      class={clsx(styles.triggerItem, local.class)}
      {...others}
      data-slot="menu-trigger-item"
    />
  );
}

function MenuTriggerItemIcon(props: ComponentProps<'span'>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <span
      class={clsx(styles.triggerItemIcon, local.class)}
      {...others}
      data-slot="menu-trigger-item-icon"
    >
      {resolvedChildren() ?? <ChevronRightIcon />}
    </span>
  );
}

function MenuSeparator(props: ComponentProps<typeof MenuPrimitive.Separator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.Separator
      class={clsx(styles.separator, local.class)}
      {...others}
      data-slot="menu-separator"
    />
  );
}

function MenuItemGroup(props: ComponentProps<typeof MenuPrimitive.ItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemGroup
      class={clsx(styles.itemGroup, local.class)}
      {...others}
      data-slot="menu-item-group"
    />
  );
}

function MenuItemGroupLabel(props: ComponentProps<typeof MenuPrimitive.ItemGroupLabel>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemGroupLabel
      class={clsx(styles.itemGroupLabel, local.class)}
      {...others}
      data-slot="menu-item-group-label"
    />
  );
}

function MenuRadioItemGroup(props: ComponentProps<typeof MenuPrimitive.RadioItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.RadioItemGroup
      class={clsx(styles.radioItemGroup, local.class)}
      {...others}
      data-slot="menu-radio-item-group"
    />
  );
}

function MenuRadioItem(props: MenuRadioItemProps) {
  const [local, others] = splitProps(props, ['class', 'indicator']);

  return (
    <MenuPrimitive.RadioItem
      class={clsx(styles.radioItem, local.class)}
      {...others}
      data-indicator-position={local.indicator ?? 'start'}
      data-slot="menu-radio-item"
    />
  );
}

function MenuCheckboxItem(props: MenuCheckboxItemProps) {
  const [local, others] = splitProps(props, ['class', 'indicator']);

  return (
    <MenuPrimitive.CheckboxItem
      class={clsx(styles.checkboxItem, local.class)}
      {...others}
      data-indicator-position={local.indicator ?? 'start'}
      data-slot="menu-checkbox-item"
    />
  );
}

function MenuItemIndicator(props: ComponentProps<typeof MenuPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <MenuPrimitive.ItemIndicator
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-slot="menu-item-indicator"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </MenuPrimitive.ItemIndicator>
  );
}

function MenuItemText(props: ComponentProps<typeof MenuPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <MenuPrimitive.ItemText
      class={clsx(styles.itemText, local.class)}
      {...others}
      data-slot="menu-item-text"
    />
  );
}

function MenuItemTextContent(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextContent, local.class)}
      {...others}
      data-slot="menu-item-text-content"
    />
  );
}

function MenuItemTextIcon(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextIcon, local.class)}
      {...others}
      data-slot="menu-item-text-icon"
    />
  );
}

function MenuItemTextLabel(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextLabel, local.class)}
      {...others}
      data-slot="menu-item-text-label"
    />
  );
}

function MenuItemShortcut(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemShortcut, local.class)}
      {...others}
      data-slot="menu-item-shortcut"
    />
  );
}

const MenuContext = MenuPrimitive.Context;
const MenuItemContext = MenuPrimitive.ItemContext;

export {
  Menu,
  MenuArrow,
  MenuArrowTip,
  MenuCheckboxItem,
  MenuContext,
  MenuContextTrigger,
  MenuContent,
  MenuIndicator,
  MenuItem,
  MenuItemContext,
  MenuItemGroup,
  MenuItemGroupLabel,
  MenuItemIndicator,
  MenuItemShortcut,
  MenuItemText,
  MenuItemTextContent,
  MenuItemTextIcon,
  MenuItemTextLabel,
  MenuPositioner,
  MenuRadioItem,
  MenuRadioItemGroup,
  MenuRootProvider,
  MenuSeparator,
  MenuTrigger,
  MenuTriggerItem,
  MenuTriggerItemIcon,
  MenuViewport,
  useMenu,
  useMenuContext,
  useMenuItemContext,
};

export type {
  MenuArrowProps,
  MenuArrowTipProps,
  MenuContentProps,
  MenuContextProps,
  MenuContextTriggerProps,
  MenuFocusOutsideEvent,
  MenuHighlightChangeDetails,
  MenuIndicatorProps,
  MenuInteractOutsideEvent,
  MenuItemContextProps,
  MenuItemGroupLabelProps,
  MenuItemGroupProps,
  MenuItemIndicatorProps,
  MenuItemTextProps,
  MenuOpenChangeDetails,
  MenuPointerDownOutsideEvent,
  MenuPositionerProps,
  MenuRadioItemGroupProps,
  MenuSelectionDetails,
  MenuSeparatorProps,
  MenuTriggerItemProps,
  MenuTriggerProps,
  MenuTriggerValueChangeDetails,
  MenuValueChangeDetails,
  UseMenuContext,
  UseMenuItemContext,
  UseMenuProps,
  UseMenuReturn,
} from '@ark-ui/solid/menu';

export type {
  MenuCheckboxItemProps,
  MenuIndicatorPosition,
  MenuItemProps,
  MenuItemTone,
  MenuRadioItemProps,
  MenuRootProps,
  MenuRootProviderProps,
};

@layer moduix.components {
  .indicator,
  .triggerItemIcon,
  .itemIndicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: 100%;
      height: 100%;
    }
  }

  .indicator {
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
  }

  .positioner {
    z-index: var(--z-index);
  }

  .content {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);

    position: relative;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: min(
      max(var(--reference-width, 0px), var(--moduix-menu-popup-min-width, 12rem)),
      var(--available-width, 100vw)
    );
    max-width: min(var(--moduix-menu-popup-max-width, 20rem), var(--available-width, 100vw));
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    /* An outline instead of a border lets MenuArrow paint over the edge and join it. */
    outline: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: var(--transform-origin);

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .viewport {
    display: flex;
    max-height: min(var(--moduix-menu-popup-max-height, 24rem), var(--available-height, 100dvh));
    flex-direction: column;
    overflow: auto;
  }

  .arrowTip {
    border-block-start: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-inline-start: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  .item,
  .triggerItem,
  .radioItem,
  .checkboxItem {
    position: relative;
    box-sizing: border-box;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    margin: 0;
    border: 0;
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3))
      var(--moduix-popup-item-padding-x-end, var(--moduix-spacing-3));
    outline: 0;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    text-decoration: none;
    user-select: none;
    cursor: default;

    /* The highlight is inset from the row, so the whole row stays clickable. */
    &:is([data-highlighted], [data-state='open']) {
      z-index: 0;
      color: var(--moduix-color-accent-foreground);

      &::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset-block: 0;
        inset-inline: var(--moduix-popup-highlight-inset-x, var(--moduix-spacing-1));
        border-radius: var(--moduix-popup-highlight-radius, var(--moduix-radius-sm));
        background-color: var(--moduix-color-accent);
      }
    }

    &[data-tone='destructive'] {
      color: var(--moduix-color-destructive);

      &[data-highlighted]::before {
        background-color: color-mix(in oklab, var(--moduix-color-destructive) 12%, transparent);
      }
    }

    /* After the tone, so a disabled destructive item is muted too. */
    &[data-disabled] {
      pointer-events: none;
      color: var(--moduix-color-muted-foreground);
    }
  }

  .item {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .triggerItem {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-3);
  }

  .triggerItemIcon {
    width: var(--moduix-spacing-3-5);
    height: var(--moduix-spacing-3-5);

    &:dir(rtl) {
      transform: scaleX(-1);
    }
  }

  .itemGroup,
  .radioItemGroup {
    display: grid;
  }

  .itemGroupLabel {
    margin: 0;
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-group-label-padding-x-start, var(--moduix-spacing-2-5))
      var(--moduix-popup-group-label-padding-x-end, var(--moduix-spacing-3));
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
    user-select: none;
    cursor: default;
  }

  .radioItem,
  .checkboxItem {
    --_menu-indicator-size: var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3));

    display: grid;
    grid-template-columns: var(--_menu-indicator-size) minmax(0, 1fr);
    align-items: center;
    gap: var(--moduix-popup-check-gap, var(--moduix-spacing-2));
    padding-inline-start: var(--moduix-popup-check-padding-x-start, var(--moduix-spacing-2-5));

    &[data-indicator-position='none'] {
      grid-template-columns: minmax(0, 1fr);
      padding-inline-start: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));

      & > .itemIndicator {
        display: none;
      }

      & > .itemText {
        grid-column-start: 1;
      }
    }

    &[data-indicator-position='end'] {
      grid-template-columns: minmax(0, 1fr) var(--_menu-indicator-size);

      & > .itemText {
        grid-column-start: 1;
      }

      & > .itemIndicator {
        grid-column-start: 2;
        justify-self: end;
      }
    }
  }

  .itemIndicator {
    grid-column-start: 1;
    width: var(--_menu-indicator-size, var(--moduix-spacing-3));
    height: var(--_menu-indicator-size, var(--moduix-spacing-3));
  }

  .itemText {
    grid-column-start: 2;
    min-width: 0;
    overflow: hidden;
  }

  .itemTextContent {
    display: inline-flex;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemShortcut {
    margin-inline-start: auto;
    padding-inline-start: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
    white-space: nowrap;
  }

  .separator {
    box-sizing: border-box;
    height: var(--moduix-border-width-sm);
    margin-block: var(--moduix-popup-separator-margin-y, var(--moduix-spacing-1-5));
    margin-inline: var(--moduix-popup-separator-margin-x-start, var(--moduix-spacing-3))
      var(--moduix-popup-separator-margin-x-end, var(--moduix-spacing-3));
    border: 0;
    background-color: var(--moduix-color-border);
  }

  @media (prefers-reduced-motion: reduce) {
    .content[data-state] {
      animation-delay: 0ms;
      animation-duration: 1ms;
    }
  }
}
